#include <stdint.h>

#if !defined(__SOFT_FP__) && defined(__ARM_FP)
  #warning "FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."
#endif

#define RCC_AHB2ENR  (*(volatile uint32_t *)0x4002104C)

#define GPIOA_MODER  (*(volatile uint32_t *)0x48000000)
#define GPIOA_PUPDR  (*(volatile uint32_t *)0x4800000C)

#define GPIOA_IDR 	 (*(volatile uint32_t *)0x48000010)
#define GPIOA_ODR    (*(volatile uint32_t *)0x48000014)

#define GPIOC_MODER (*(volatile uint32_t *)0x48000800)
#define GPIOC_IDR (*(volatile uint32_t *)0x48000810)


#define STK_CTRL (*(volatile uint32_t *)0xE000E010) // control and status
#define STK_LOAD (*(volatile uint32_t *)0xE000E014) // reload value
#define STK_VAL (*(volatile uint32_t *)0xE000E018) // current value


void delay_ms(int ms){
	for (int i = 0; i <ms; i++){
		while ((STK_CTRL & (1 << 16)) == 0);
	}
}

int main(void)
{
//	1. Clock for port A (Both pins are on port a)
	RCC_AHB2ENR |= (1 << 0);

//	2. PA0 as input (pin 0 -> MODER bits 0-1 = 00
	GPIOA_MODER &= ~(3 << (0 * 2));

//	3. PA0 internal pull-up (pin 0 -> PUPDR bits 0-1 = pull-up value)

	// clear the two bits.
	GPIOA_PUPDR &= ~(3 << (0 * 2));

	// set the pull-up value
	GPIOA_PUPDR |= (1 << (0 * 2));

//	4. PA1 as output (pin 1 -> MODER bits 2-3 = 01)
	// clear
	GPIOA_MODER &= ~(3 << (1 * 2));

	// set
	GPIOA_MODER |= (1 << (1 * 2));

	while (1) {
	        if ((GPIOA_IDR & (1 << 0)) == 0) {   // button pressed (active low)
	            // LED on:  set ODR bit 1
	        	GPIOA_ODR |= (1 << 1);
	        } else {
	            // LED off: clear ODR bit 1
	        	GPIOA_ODR &= ~(1 << 1);
	        }
	    }

}
